WITH ordered AS(SELECT rr.id_user,rr.points,r.id_season,ps.best_of,row_number() OVER(PARTITION BY rr.id_user ORDER BY rr.points DESC,rr.id_round) AS score_index FROM public.zsl_round_result rr JOIN public.zsl_round r ON r.id=rr.id_round JOIN public.zsl_season s ON s.id=r.id_season JOIN public.zsl_points_structure ps ON ps.id=s.id_points_structure WHERE r.id_season=(SELECT id_season FROM public.zsl_round WHERE id=$1)), totals AS(SELECT id_user,id_season,sum(points)::integer AS points FROM ordered WHERE score_index<=best_of GROUP BY id_user,id_season), ranked AS(SELECT *,rank() OVER(ORDER BY points DESC)::integer AS position FROM totals) INSERT INTO public.zsl_season_result(id_season,id_user,points,position,date_created) SELECT id_season,id_user,points,position,clock_timestamp() FROM ranked ON CONFLICT(id_season,id_user) DO UPDATE SET points=excluded.points,position=excluded.position,date_updated=clock_timestamp()
